from ...filecollector.filecollector import FileCollector


class CollectFilesInterface(BaseClToolInterface):
    """Keywords for uploading specified files from BTS to PC.

    :note: Keywords in this class require both PW and SSH credentials because some files are transferred via the BTSSM protocol
           while others are transferred via SFTP.
    """

    OPERATION = 'collectfiles'

    def collect_btssm_files(self, unzip=None, subdirectory=None, add_files=None, **kwargs):
        """A method for downloading created files to the test result directory.

        This method will always download the following files:
            * ToolLog.xml
            * PoseidonLog.xml
            * Tool.log

        To add other files, use parameter 'add_files'.

        :param boolean unzip: Flag indicating whether to extract the logs in the result directory.
                              True, 'true' and 'True' evaluate to true, the rest is treated as false.
        :param string subdirectory: Name of folder to create in addition to the normal test result structure.
        :param list add_files: Single file or list of files to collect, in addition to default collected files.

        :note: Always provide absolute path for add_files
               This method now accepts wildcards/regexp in the add_files parameter, e.g., /tmp/*.xml, or /tmp/file[0-9].txt
               Format of the result directory structure is: TestSuite1/TestSuite2/TestCase/SubFolder
        """
        alias = kwargs.get('alias')
        alias = alias.strip() if alias else None
        config = self.command_store.get(alias).get_config()
        unzip = to_bool(unzip, skip_none=True)
        tar_name = "btssm.tar.gz" if alias is None else "btssm_{}.tar.gz".format(alias)
        if isinstance(add_files, six.string_types):
            add_files = [add_files]
        files_list = self._create_collect_files_list(config.log_path, add_files)
        subdirectory = subdirectory.strip() if subdirectory is not None else None
        with new_session.NewSession(alias, config) as session:
            FileCollector(session.executor, tar_name=tar_name).get_files(files_list=files_list, unzip=unzip, subdirectory=subdirectory)

    def _create_collect_files_list(self, log_path, add_files):
        files_list = ['{}/ToolLog.xml'.format(log_path), '{}/PoseidonLog.xml'.format(log_path), '{}/Tool.log'.format(log_path)]
        if add_files is None:
            return files_list

        for each in add_files:
            files_list.append(each)
        return files_list

    def upload_all_bts_files(self, conn_num=None, ssh=ENBConfig.ssh, timeout='1h', **kwargs):
        """Upload "all files" from BTS to PC.

        :param integer conn_num: Number of concurrent connections to BTS to speed-up the upload operation.

        :return: Path(s) of collected file(s).
        :rtype: list

        :note: Library will upload all files from BTS to PC specified by upload* keywords.
        """
        alias = kwargs.get('alias')
        alias = alias.strip() if alias else None
        timeout = self._convert_to_secs(timeout)
        config = self.command_store.get(alias).get_config()
        ne = kwargs.get('ne', config.trs_ip).strip()
        pw = kwargs.get('pw', config.pw).strip()
        params = {'ne': ne, 'pw': pw, 'ssh': ssh, 'concurrent': conn_num, 'timeout': timeout}
        nolog = config.nolog if kwargs.get('nolog') is None else kwargs.get('nolog')
        flags = ['all']
        if nolog:
            flags.append('nolog')
        return self._execute_cl_tool_operation(alias=alias, timeout=timeout, operation=CollectFilesInterface.OPERATION, params=params,
                                               flags=flags, trs_ip=ne)

