    def upload_file_from_bts(self, filepath, filename=None, ssh=ENBConfig.ssh, timeout='15min', **kwargs):
        """*DEPRECATED*
        This keyword is not supported anymore due to LBT3706.
        Use ute_fsmaccess keyword "Get Enb File" to get desired file instead.

        :raises: BTSSMExecutionError
        """
        raise BTSSMExecutionError('This keyword is not supported anymore due to LBT3706. '
                                  'Please use ute_fsmaccess keyword "Get Enb File" to get desired file instead.')

